// Isolated manual Build: presentation bootstrap plus read-only startup observations.
// No input injection, trajectory writes, screenshots, auto-pause, or auto-exit.
using System;
using System.Collections;
using HimoHitoA2Proof;
using UnityEngine;

namespace HimoHito
{
    public sealed class ManualPresentationSession : MonoBehaviour
    {
        A2Fixture fixture;
        float startRealtime, startScaled;

        IEnumerator Start()
        {
            while(!(fixture=A2Fixture.Instance)||!fixture.Ready)yield return null;
            if(PlayerPresentationProof.Candidate&&!fixture.Body.GetComponent<PlayerMotionPresentation>())
                fixture.Body.gameObject.AddComponent<PlayerMotionPresentation>();
            startRealtime=Time.realtimeSinceStartup;startScaled=Time.time;
            yield return null;
            Observe("00_Ready");
            yield return new WaitForSecondsRealtime(2);Observe("01_Idle2s");
            yield return new WaitForSecondsRealtime(13);Observe("02_Idle15s");
            yield return new WaitForSecondsRealtime(20);Observe("03_Idle35s");
            // Intentionally keep playing. No completion, movement, pause, or quit command.
        }

        void Observe(string label)
        {
            fixture.Write("Manual_"+label+".json",new Snapshot(fixture,this));
            Debug.Log("MANUAL_PRESENTATION "+label+" "+(PlayerPresentationProof.SecondCandidate?"candidate2":"candidate1"));
        }

        [Serializable] public class Snapshot
        {
            public string method="Read-only observation. No OS keys, internal input/API driving, screenshot, or audio assessment.",candidate;
            public bool manual,secondCandidate,moverEnabled,ropeEnabled,bodySimulated,layoutUnchanged,shaderSupported;
            public float realtimeElapsed,scaledElapsed,captureDeltaTime,timeScale,fixedDeltaTime;
            public int captureFramerate,presentationComponents,captureDrivers,inputDrivers,qaDrivers;
            public A2Fixture.Observation state;
            public Snapshot(A2Fixture f,ManualPresentationSession s)
            {
                candidate=A2Fixture.Arg("-presentation","candidate2");manual=PlayerPresentationProof.Manual;
                secondCandidate=PlayerPresentationProof.SecondCandidate;
                realtimeElapsed=Time.realtimeSinceStartup-s.startRealtime;scaledElapsed=Time.time-s.startScaled;
                captureDeltaTime=Time.captureDeltaTime;captureFramerate=Time.captureFramerate;
                timeScale=Time.timeScale;fixedDeltaTime=Time.fixedDeltaTime;
                moverEnabled=f.Mover.enabled;ropeEnabled=f.Rope.enabled;bodySimulated=f.Body.simulated;
                presentationComponents=f.Body.GetComponents<PlayerMotionPresentation>().Length;
                captureDrivers=FindObjectsByType<PresentationCapture>(FindObjectsInactive.Include,FindObjectsSortMode.None).Length;
                inputDrivers=FindObjectsByType<A2InputDriver>(FindObjectsInactive.Include,FindObjectsSortMode.None).Length;
                qaDrivers=FindObjectsByType<A2ScriptedQA>(FindObjectsInactive.Include,FindObjectsSortMode.None).Length;
                layoutUnchanged=JsonUtility.ToJson(new A2Fixture.Layout(f))==f.ExpectedLayout;
                shaderSupported=Resources.Load<Shader>("PlayerPresentationYarn")?.isSupported==true;
                state=new A2Fixture.Observation(f,"Manual session, observation only");
            }
        }
    }
}
